import sys

class Node:
    __slots__ = ('value', 'prev', 'next')
    def __init__(self, value):
        self.value = value
        self.prev = None
        self.next = None

def main():
    head = None
    tail = None
    n = int(sys.stdin.readline())
    for _ in range(n):
        parts = sys.stdin.readline().split()
        if parts[0] == 'insert':
            x = int(parts[1])
            new_node = Node(x)
            if head is None:
                head = new_node
                tail = new_node
            else:
                new_node.next = head
                head.prev = new_node
                head = new_node
        elif parts[0] == 'delete':
            x = int(parts[1])
            current = head
            while current is not None:
                if current.value == x:
                    if current.prev is None:  # head
                        head = current.next
                        if head is not None:
                            head.prev = None
                        else:
                            tail = None
                    elif current.next is None:  # tail
                        tail = current.prev
                        if tail is not None:
                            tail.next = None
                        else:
                            head = None
                    else:
                        prev_node = current.prev
                        next_node = current.next
                        prev_node.next = next_node
                        next_node.prev = prev_node
                    break
                current = current.next
        elif parts[0] == 'deleteFirst':
            if head is not None:
                temp = head
                head = head.next
                if head is not None:
                    head.prev = None
                else:
                    tail = None
        elif parts[0] == 'deleteLast':
            if tail is not None:
                temp = tail
                tail = tail.prev
                if tail is not None:
                    tail.next = None
                else:
                    head = None
    # Collect the elements
    result = []
    current = head
    while current is not None:
        result.append(str(current.value))
        current = current.next
    print(' '.join(result))

